from sqlalchemy.orm import Mapped, mapped_column, DeclarativeBase
from sqlalchemy import event, Boolean

class Base(DeclarativeBase):
    pass

# Use the 'init' event on Base to apply column defaults
@event.listens_for(Base, 'init', propagate=True)
def apply_column_defaults(target, args, kwargs):
    for attr in target.__mapper__.column_attrs:
        col = attr.columns[0]
        key = attr.key
        if key not in kwargs and col.default is not None:
            default = col.default
            if default.is_scalar:
                setattr(target, key, default.arg)
            elif default.is_callable:
                setattr(target, key, default.arg(None))

class TestModel(Base):
    __tablename__ = 'test'
    id: Mapped[int] = mapped_column(primary_key=True)
    flag: Mapped[bool] = mapped_column(Boolean, default=True)

